require_once __DIR__.'/banco.php'; require_once __DIR__.'/../auth.php'; $pdo=cobrancaDb(); authInit($pdo);
if(!authLogged()){header('Location: ../login.php');exit;} authRequirePermission($pdo,'app.cobranca',false);
