<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Central de Cobrança • Liceu Brasil</title>
<style>
*{box-sizing:border-box}body{margin:0;background:#f4f7fb;color:#172033;font-family:Inter,system-ui,-apple-system,Segoe UI,sans-serif}.app{display:grid;grid-template-columns:235px 1fr;min-height:100vh}.side{background:#0b5dac;color:#fff;padding:22px 15px;position:sticky;top:0;height:100vh}.logo{height:38px;max-width:160px;object-fit:contain;margin:0 8px 24px}.brand{font-weight:900;font-size:18px;margin:0 10px 22px}.nav button{width:100%;border:0;background:transparent;color:#dcecff;text-align:left;padding:12px;border-radius:10px;font-weight:750;cursor:pointer;margin:2px 0}.nav button.active,.nav button:hover{background:rgba(255,255,255,.15);color:#fff}.main{padding:24px;min-width:0}.top{display:flex;align-items:center;justify-content:space-between;margin-bottom:22px}.top h1{margin:0;font-size:25px}.muted{color:#718096;font-size:13px}.cards{display:grid;grid-template-columns:repeat(5,1fr);gap:12px;margin-bottom:18px}.card{background:#fff;border:1px solid #e4eaf2;border-radius:14px;padding:16px;box-shadow:0 3px 12px rgba(16,24,40,.04)}.card small{color:#748197;font-weight:750}.num{font-size:25px;font-weight:900;margin-top:6px}.toolbar{display:grid;grid-template-columns:1fr 190px 190px;gap:10px;margin-bottom:12px}.input,.select,.textarea{width:100%;border:1px solid #d8e0eb;background:#fff;border-radius:10px;padding:10px 12px;font:inherit}.tablebox{background:#fff;border:1px solid #e4eaf2;border-radius:14px;overflow:auto}.table{width:100%;border-collapse:collapse;min-width:1030px}.table th{font-size:11px;text-transform:uppercase;letter-spacing:.04em;color:#728096;background:#f8fafc;padding:11px;text-align:left}.table td{padding:12px 11px;border-top:1px solid #edf1f6;font-size:13px}.badge{display:inline-block;padding:5px 8px;border-radius:999px;font-size:11px;font-weight:850}.red{background:#feecec;color:#b42318}.orange{background:#fff3df;color:#a15c00}.blue{background:#eaf3ff;color:#0b5dac}.green{background:#e9f8ef;color:#16794a}.btn{border:0;border-radius:9px;padding:8px 10px;font-weight:800;cursor:pointer}.btn.primary{background:#0b63bd;color:white}.btn.light{background:#eef4fb;color:#0b5dac}.modalbg{position:fixed;inset:0;background:rgba(15,23,42,.45);display:none;align-items:center;justify-content:center;padding:18px;z-index:50}.modalbg.show{display:flex}.modal{background:#fff;width:min(760px,100%);max-height:90vh;overflow:auto;border-radius:16px;box-shadow:0 24px 60px rgba(0,0,0,.22)}.mhead{padding:18px 20px;border-bottom:1px solid #e9edf3;display:flex;justify-content:space-between}.mbody{padding:18px 20px}.grid2{display:grid;grid-template-columns:1fr 1fr;gap:12px}.hist{margin-top:16px;border-top:1px solid #edf1f6}.histitem{padding:12px 0;border-bottom:1px solid #edf1f6}.close{background:none;border:0;font-size:24px;cursor:pointer}@media(max-width:1050px){.cards{grid-template-columns:repeat(2,1fr)}.app{grid-template-columns:82px 1fr}.side .brand,.side .label{display:none}.toolbar{grid-template-columns:1fr}}@media(max-width:650px){.main{padding:14px}.cards{grid-template-columns:1fr 1fr}.grid2{grid-template-columns:1fr}}
</style></head><body><div class="app"><aside class="side"><img class="logo" src="logo-liceu.png"><div class="brand">Central de Cobrança</div><div class="nav"><button class="active">▦ <span class="label">Dashboard</span></button><button onclick="focarFila()">⚠ <span class="label">Fila de cobrança</span></button><button>🤝 <span class="label">Acordos</span></button><button>◷ <span class="label">Contatos</span></button><button onclick="location.href='../mapa/'">← <span class="label">Voltar ao Mapa</span></button></div></aside><main class="main"><div class="top"><div><h1>Central de Cobrança</h1><div class="muted" id="relInfo">Carregando relatório financeiro...</div></div><div class="muted">👤 <?=htmlspecialchars((string)($_SESSION['auth_nome']??''))?></div></div>
<div class="cards"><div class="card"><small>Valor total em aberto</small><div class="num" id="kTotal">—</div></div><div class="card"><small>Matrículas inadimplentes</small><div class="num" id="kMat">—</div></div><div class="card"><small>Alunos em cobrança</small><div class="num" id="kAlunos">—</div></div><div class="card"><small>Promessas ativas</small><div class="num" id="kPromessas">—</div></div><div class="card"><small>Nunca contatados</small><div class="num" id="kNunca">—</div></div></div>
<section id="fila"><div class="toolbar"><input id="busca" class="input" placeholder="Buscar aluno, turma ou telefone..." oninput="render()"><select id="status" class="select" onchange="render()"><option value="">Todos os status</option><option value="pendente">Pendente</option><option value="em_cobranca">Em cobrança</option><option value="promessa">Promessa</option><option value="acordo">Acordo</option></select><select id="ordem" class="select" onchange="render()"><option value="valor">Maior dívida</option><option value="nome">Nome</option><option value="meses">Mais meses</option></select></div>
<div class="tablebox"><table class="table"><thead><tr><th>Aluno</th><th>Curso/Turma</th><th>Contato</th><th>Meses</th><th>Em aberto</th><th>Financeiro</th><th>Cobrança</th><th>Último contato</th><th>Ações</th></tr></thead><tbody id="tbody"></tbody></table></div></section></main></div>
<div class="modalbg" id="modal"><div class="modal"><div class="mhead"><div><b id="mAluno"></b><div class="muted" id="mTurma"></div></div><button class="close" onclick="fechar()">×</button></div><div class="mbody"><div class="grid2"><div><small>Telefone</small><div id="mTel"></div></div><div><small>Total em aberto</small><div id="mValor"></div></div><div><small>Meses inadimplentes</small><div id="mMeses"></div></div><div><small>Status da cobrança</small><div id="mStatus"></div></div></div><hr style="border:0;border-top:1px solid #edf1f6;margin:18px 0"><h3>Registrar contato</h3><div class="grid2"><select id="canal" class="select"><option value="whatsapp">WhatsApp</option><option value="telefone">Telefone</option><option value="presencial">Presencial</option><option value="email">E-mail</option></select><select id="resultado" class="select" onchange="togglePromessa()"><option value="contato_realizado">Contato realizado</option><option value="sem_resposta">Sem resposta</option><option value="retornar">Retornar depois</option><option value="promessa_pagamento">Promessa de pagamento</option><option value="acordo_firmado">Acordo firmado</option><option value="regularizado">Informou regularização</option></select><input id="proximo" class="input" type="date" aria-label="Próximo contato"><div id="promessaBox" style="display:none"><input id="promessaData" class="input" type="date" style="margin-bottom:8px"><input id="promessaValor" class="input" type="number" step="0.01" placeholder="Valor prometido"></div></div><textarea id="obs" class="textarea" rows="3" placeholder="Observações do contato..." style="margin-top:10px"></textarea><div style="display:flex;gap:8px;justify-content:flex-end;margin-top:10px"><button class="btn light" onclick="abrirWhatsapp()">Abrir WhatsApp</button><button class="btn primary" onclick="salvarContato()">Salvar contato</button></div><h3 style="margin-top:22px">Histórico</h3><div class="hist" id="historico"></div></div></div></div>
<script>
let dados=[],atual=null; const brl=v=>(Number(v)||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'}); const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
async function api(url,opt){const r=await fetch(url,opt);const j=await r.json();if(!r.ok||!j.ok)throw new Error(j.error||'Erro');return j}
async function carregar(){try{const j=await api('api.php?action=dashboard');dados=j.itens||[];kTotal.textContent=brl(j.resumo.totalAberto);kMat.textContent=j.resumo.matriculas;kAlunos.textContent=j.resumo.alunos;kPromessas.textContent=j.resumo.promessas;kNunca.textContent=j.resumo.nuncaContatados;relInfo.textContent=j.relatorio?`Relatório Sponte: ${j.relatorio.arquivo||'último importado'} • ${j.relatorio.importado_em||''}`:'Sem relatório Sponte: exibindo casos manuais/estimados.';render()}catch(e){relInfo.textContent=e.message}}
function badgeStatus(s){const map={pendente:['Pendente','orange'],em_cobranca:['Em cobrança','blue'],promessa:['Promessa','green'],acordo:['Acordo','green'],regularizado:['Regularizado','green']};const x=map[s]||[s,'orange'];return `<span class="badge ${x[1]}">${x[0]}</span>`}
function render(){const q=busca.value.toLowerCase().trim(),st=status.value,ord=ordem.value;let a=dados.filter(x=>(!q||`${x.aluno} ${x.turma} ${x.telefone||''}`.toLowerCase().includes(q))&&(!st||x.cobrancaStatus===st));a.sort((x,y)=>ord==='nome'?x.aluno.localeCompare(y.aluno):ord==='meses'?y.mesesInadimplencia-x.mesesInadimplencia:y.totalAberto-x.totalAberto);tbody.innerHTML=a.map(x=>`<tr><td><b>${esc(x.aluno)}</b><div class="muted">Matrícula interna #${x.matriculaId}</div></td><td>${esc(x.turma)}<div class="muted">${esc(x.dia)} • ${esc(x.horario)}</div></td><td>${esc(x.telefone||'—')}</td><td>${x.mesesInadimplencia||0}</td><td><b>${brl(x.totalAberto)}</b></td><td><span class="badge red">Inadimplente</span></td><td>${badgeStatus(x.cobrancaStatus)}</td><td>${esc(x.ultimoContato||'Nunca')}</td><td><button class="btn primary" onclick="abrir(${x.matriculaId})">Atender</button></td></tr>`).join('')||'<tr><td colspan="9" style="text-align:center;padding:30px;color:#718096">Nenhum inadimplente encontrado neste filtro.</td></tr>'}
function focarFila(){document.getElementById('fila').scrollIntoView({behavior:'smooth'})}
async function abrir(mid){atual=dados.find(x=>x.matriculaId===mid);if(!atual)return;mAluno.textContent=atual.aluno;mTurma.textContent=atual.turma+' • '+atual.dia+' '+atual.horario;mTel.textContent=atual.telefone||'—';mValor.textContent=brl(atual.totalAberto);mMeses.textContent=atual.mesesInadimplencia||0;mStatus.innerHTML=badgeStatus(atual.cobrancaStatus);modal.classList.add('show');await historicoCarregar()}
function fechar(){modal.classList.remove('show');atual=null}function togglePromessa(){promessaBox.style.display=resultado.value==='promessa_pagamento'?'block':'none'}
async function historicoCarregar(){const j=await api('api.php?action=historico&matriculaId='+atual.matriculaId);historico.innerHTML=(j.historico||[]).map(h=>`<div class="histitem"><b>${esc(h.usuario_nome||'Sistema')}</b> • ${esc(h.canal)} • ${esc(h.resultado)}<div class="muted">${esc(h.criado_em)}</div><div>${esc(h.observacao||'')}</div>${h.promessa_data?`<div class="muted">Promessa: ${esc(h.promessa_data)} • ${brl(h.promessa_valor)}</div>`:''}</div>`).join('')||'<div class="muted">Nenhum contato registrado.</div>'}
async function salvarContato(){if(!atual)return;try{await api('api.php?action=registrar_contato',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({matriculaId:atual.matriculaId,canal:canal.value,resultado:resultado.value,observacao:obs.value,proximoContato:proximo.value,promessaData:promessaData.value,promessaValor:promessaValor.value})});obs.value='';proximo.value='';promessaData.value='';promessaValor.value='';await carregar();atual=dados.find(x=>x.matriculaId===atual.matriculaId);await historicoCarregar();mStatus.innerHTML=badgeStatus(atual?.cobrancaStatus||'em_cobranca')}catch(e){alert(e.message)}}
function abrirWhatsapp(){if(!atual)return;const tel=String(atual.responsavelTelefone||atual.telefone||'').replace(/\D/g,'');if(!tel){alert('Sem telefone cadastrado.');return}const msg=`Olá, tudo bem? Aqui é do Liceu Brasil. Gostaríamos de conversar sobre uma pendência financeira referente ao curso ${atual.turma}. Podemos ajudar com alguma dúvida ou forma de regularização?`;window.open('https://wa.me/55'+tel.replace(/^55/,'')+'?text='+encodeURIComponent(msg),'_blank')}
modal.addEventListener('click',e=>{if(e.target===modal)fechar()});carregar();
</script>
